#define MAX_LINES 100
#define EPS 1e-9

typedef struct {
    double a, b, c;
} Line;

int read_line(Line *l) {
    return scanf("%lf %lf %lf", &l->a, &l->b, &l->c) == 3;
}

int solve_2x2(double a1, double b1, double c1,
              double a2, double b2, double c2,
              double *x, double *y) {
    double det = a1 * b2 - a2 * b1;
    if (fabs(det) < EPS) return 0; // no unique solution
    *x = (c1 * b2 - c2 * b1) / det;
    *y = (a1 * c2 - a2 * c1) / det;
    return 1;
}

int main() {
    Line lines[MAX_LINES];
    int n = 0;
    while (n < MAX_LINES && read_line(&lines[n])) {
        n++;
    }
    if (n == 0) {
        printf("No solution\n");
        return 0;
    }

    // Try to find intersection point of first two lines
    double x, y;
    if (n == 1) {
        // Single line: infinite points
        printf("Multiple solutions\n");
        return 0;
    }

    // Try plus sign for first two lines
    if (!solve_2x2(lines[0].a, lines[0].b, -lines[0].c,
                   lines[1].a, lines[1].b, -lines[1].c,
                   &x, &y)) {
        // Parallel first two lines
        // Check if they are the same line
        double ratio = lines[0].a / lines[1].a;
        if (fabs(lines[0].b * ratio - lines[1].b) < EPS &&
            fabs(lines[0].c * ratio - lines[1].c) < EPS) {
            // Same line: multiple solutions
            printf("Multiple solutions\n");
        } else {
            printf("No solution\n");
        }
        return 0;
    }

    // Check distances for all lines
    double d0 = fabs(lines[0].a * x + lines[0].b * y + lines[0].c);
    for (int i = 1; i < n; i++) {
        double di = fabs(lines[i].a * x + lines[i].b * y + lines[i].c);
        if (fabs(di - d0) > EPS) {
            printf("No solution\n");
            return 0;
        }
    }
    printf("%.6f %.6f\n", x, y);
    return 0;
}

