static int dcmp(double x) {
    if (x > EPS) return 1;
    if (x < -EPS) return -1;
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    if (n <= 0) {
        printf("no solution\n");
        return 0;
    }

    Line *L = (Line *)malloc(sizeof(Line) * n);
    if (!L) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%lf %lf %lf", &L[i].a, &L[i].b, &L[i].c);
    }

    /* Each line gives:
       |a x + b y + c| / sqrt(a^2+b^2) = d
       So for chosen signs s_i in {+1,-1}:
       a x + b y + c = s_i * norm_i * d
       Rearranged:
       a x + b y - s_i*norm_i*d = -c
       Unknowns: x, y, d
    */

    int totalMasks = 1 << n;
    int found = 0;
    double ansx = 0.0, ansy = 0.0;

    for (int mask = 0; mask < totalMasks; mask++) {
        double M[3][4];

        /* Build up to 3 independent equations from the system */
        int rank = 0;
        for (int i = 0; i < n; i++) {
            double norm = sqrt(L[i].a * L[i].a + L[i].b * L[i].b);
            double row[4];
            int s = ((mask >> i) & 1) ? 1 : -1;
            row[0] = L[i].a;
            row[1] = L[i].b;
            row[2] = -s * norm;
            row[3] = -L[i].c;

            /* Insert row into basis by elimination */
            for (int r = 0; r < rank; r++) {
                int pivot = -1;
                for (int k = 0; k < 3; k++) {
                    if (dcmp(M[r][k]) != 0) {
                        pivot = k;
                        break;
                    }
                }
                if (pivot != -1 && dcmp(row[pivot]) != 0) {
                    double factor = row[pivot] / M[r][pivot];
                    for (int k = pivot; k < 4; k++) row[k] -= factor * M[r][k];
                }
            }

            int pivot = -1;
            for (int k = 0; k < 3; k++) {
                if (dcmp(row[k]) != 0) {
                    pivot = k;
                    break;
                }
            }

            if (pivot == -1) {
                if (dcmp(row[3]) != 0) {
                    rank = -1; /* inconsistent */
                    break;
                }
            } else {
                for (int k = 0; k < 4; k++) M[rank][k] = row[k];
                /* normalize for stability */
                double div = M[rank][pivot];
                for (int k = pivot; k < 4; k++) M[rank][k] /= div;

                /* eliminate previous rows */
                for (int r = 0; r < rank; r++) {
                    if (dcmp(M[r][pivot]) != 0) {
                        double factor = M[r][pivot];
                        for (int k = pivot; k < 4; k++) M[r][k] -= factor * M[rank][k];
                    }
                }
                rank++;
                if (rank == 3) {
                    /* still must check remaining equations */
                    for (int j = i + 1; j < n; j++) {
                        double norm2 = sqrt(L[j].a * L[j].a + L[j].b * L[j].b);
                        double row2[4];
                        int s2 = ((mask >> j) & 1) ? 1 : -1;
                        row2[0] = L[j].a;
                        row2[1] = L[j].b;
                        row2[2] = -s2 * norm2;
                        row2[3] = -L[j].c;

                        for (int r = 0; r < 3; r++) {
                            int pv = -1;
                            for (int k = 0; k < 3; k++) {
                                if (dcmp(M[r][k]) != 0) {
                                    pv = k;
                                    break;
                                }
                            }
                            if (pv != -1 && dcmp(row2[pv]) != 0) {
                                double factor = row2[pv] / M[r][pv];
                                for (int k = pv; k < 4; k++) row2[k] -= factor * M[r][k];
                            }
                        }
                        if (dcmp(row2[0]) == 0 && dcmp(row2[1]) == 0 && dcmp(row2[2]) == 0 && dcmp(row2[3]) != 0) {
                            rank = -1;
                            break;
                        }
                    }
                    break;
                }
            }
        }

        if (rank != 3) continue;

        /* Extract solution from reduced 3x4 matrix */
        double sol[3] = {0, 0, 0};
        for (int r = 0; r < 3; r++) {
            int pivot = -1;
            for (int k = 0; k < 3; k++) {
                if (dcmp(M[r][k]) != 0) {
                    pivot = k;
                    break;
                }
            }
            if (pivot == -1) {
                rank = -1;
                break;
            }
            sol[pivot] = M[r][3];
        }
        if (rank == -1) continue;

        double x = sol[0], y = sol[1], d = sol[2];
        if (dcmp(d) < 0) continue;

        /* Verify against all lines with actual distances */
        int ok = 1;
        for (int i = 0; i < n; i++) {
            double norm = sqrt(L[i].a * L[i].a + L[i].b * L[i].b);
            double dist = fabs(L[i].a * x + L[i].b * y + L[i].c) / norm;
            if (fabs(dist - d) > 1e-7) {
                ok = 0;
                break;
            }
        }
        if (!ok) continue;

        if (!found) {
            found = 1;
            ansx = x;
            ansy = y;
        } else {
            if (fabs(ansx - x) > 1e-7 || fabs(ansy - y) > 1e-7) {
                printf("multiple solutions\n");
                free(L);
                return 0;
            }
        }
    }

    if (!found) {
        printf("no solution\n");
    } else {
        printf("%.10f %.10f\n", ansx, ansy);
    }

    free(L);
    return 0;
}

