bool solve3x3(double A[3][4], double &x, double &y, double &r) {
    for (int col = 0; col < 3; ++col) {
        int pivot = col;
        for (int i = col; i < 3; ++i) {
            if (fabs(A[i][col]) > fabs(A[pivot][col])) pivot = i;
        }
        if (fabs(A[pivot][col]) < EPS) return false;
        if (pivot != col) {
            for (int j = col; j < 4; ++j) swap(A[pivot][j], A[col][j]);
        }
        double div = A[col][col];
        for (int j = col; j < 4; ++j) A[col][j] /= div;
        for (int i = 0; i < 3; ++i) {
            if (i == col) continue;
            double factor = A[i][col];
            for (int j = col; j < 4; ++j) A[i][j] -= factor * A[col][j];
        }
    }
    x = A[0][3];
    y = A[1][3];
    r = A[2][3];
    return true;
}

