/*
We are given several lines in the plane and must report the point that is
equidistant from all of them, if it is unique.

A point P is equidistant from two lines iff it lies on one of their angle
bisectors. For lines
    a1 x + b1 y + c1 = 0
    a2 x + b2 y + c2 = 0
the bisectors satisfy
    (a1 x + b1 y + c1)/sqrt(a1^2+b1^2) = ± (a2 x + b2 y + c2)/sqrt(a2^2+b2^2)

For all lines to have the same distance to P, it is enough to require that
for every i>0,
    normalized(line_i)(P) = s_i * normalized(line_0)(P)
where s_i is either +1 or -1.

Each choice of signs gives a linear system in x,y,t:
    Ai x + Bi y + Ci = s_i * t
where t is the common signed normalized distance to line 0.
Rearranged:
    Ai x + Bi y - s_i t = -Ci

Unknowns are x,y,t. There are at most 2^(n-1) sign patterns. For each pattern,
we solve the linear system and check whether a solution exists. Every solution
gives a point (x,y). Distinct points among all sign patterns are candidate
points equidistant from all lines.

Result:
- no candidate points -> "None"
- exactly one distinct point -> print it
- more than one distinct point -> "Many"

This matches the geometric fact that intersections of angle bisectors can yield
0, 1, or multiple points.

Input format is not explicitly specified in the statement, so we use the common:
first integer n, followed by n lines each containing a b c for line
ax + by + c = 0.
*/

public class Main {
    static final double EPS = 1e-9;

    static class Line {
        double a, b, c; // normalized so sqrt(a^2+b^2)=1
        Line(double a, double b, double c) {
            double d = Math.hypot(a, b);
            this.a = a / d;
            this.b = b / d;
            this.c = c / d;
            // canonical direction to avoid duplicate opposite representations
            if (this.a < -EPS || (Math.abs(this.a) <= EPS && this.b < -EPS)) {
                this.a = -this.a;
                this.b = -this.b;
                this.c = -this.c;
            }
        }
    }

    static class Point {
        double x, y;
        Point(double x, double y) { this.x = x; this.y = y; }
    }

    static boolean samePoint(Point p, Point q) {
        return Math.abs(p.x - q.x) <= 1e-7 && Math.abs(p.y - q.y) <= 1e-7;
    }

    // Solve linear system M * [x y t]^T = rhs
    // equations count may be >= 1
    static double[] solve(double[][] M, double[] rhs) {
        int m = M.length;
        int vars = 3;
        double[][] a = new double[m][vars + 1];
        for (int i = 0; i < m; i++) {
            System.arraycopy(M[i], 0, a[i], 0, vars);
            a[i][vars] = rhs[i];
        }

        int row = 0;
        int[] where = new int[vars];
        Arrays.fill(where, -1);

        for (int col = 0; col < vars && row < m; col++) {
            int sel = row;
            for (int i = row; i < m; i++) {
                if (Math.abs(a[i][col]) > Math.abs(a[sel][col])) sel = i;
            }
            if (Math.abs(a[sel][col]) < EPS) continue;
            double[] tmp = a[sel]; a[sel] = a[row]; a[row] = tmp;
            where[col] = row;

            double div = a[row][col];
            for (int j = col; j <= vars; j++) a[row][j] /= div;

            for (int i = 0; i < m; i++) {
                if (i == row) continue;
                double factor = a[i][col];
                if (Math.abs(factor) < EPS) continue;
                for (int j = col; j <= vars; j++) {
                    a[i][j] -= factor * a[row][j];
                }
            }
            row++;
        }

        for (int i = 0; i < m; i++) {
            boolean allZero = true;
            for (int j = 0; j < vars; j++) {
                if (Math.abs(a[i][j]) > EPS) {
                    allZero = false;
                    break;
                }
            }
            if (allZero && Math.abs(a[i][vars]) > EPS) return null; // inconsistent
        }

        double[] ans = new double[vars];
        for (int j = 0; j < vars; j++) {
            if (where[j] != -1) ans[j] = a[where[j]][vars];
            else ans[j] = Double.NaN; // free variable
        }

        // Need unique x,y. t may be free only if x,y still uniquely determined,
        // but under this representation easier to reject non-unique systems.
        // If x or y is free => multiple points for this sign pattern.
        if (Double.isNaN(ans[0]) || Double.isNaN(ans[1])) return new double[]{Double.NaN, Double.NaN, Double.NaN};
        if (Double.isNaN(ans[2])) ans[2] = 0.0;
        return ans;
    }

