        List<Point> pts = new ArrayList<>();

        int patterns = 1 << (n - 1);
        for (int mask = 0; mask < patterns; mask++) {
            double[][] M = new double[n][3];
            double[] rhs = new double[n];

            // base equation: a0 x + b0 y - t = -c0
            M[0][0] = lines[0].a;
            M[0][1] = lines[0].b;
            M[0][2] = -1.0;
            rhs[0] = -lines[0].c;

            for (int i = 1; i < n; i++) {
                int s = ((mask >> (i - 1)) & 1) == 0 ? 1 : -1;
                M[i][0] = lines[i].a;
                M[i][1] = lines[i].b;
                M[i][2] = -s;
                rhs[i] = -lines[i].c;
            }

            double[] sol = solve(M, rhs);
            if (sol == null) continue; // no solution for this sign pattern
            if (Double.isNaN(sol[0]) || Double.isNaN(sol[1])) {
                // infinitely many points for this sign pattern
                System.out.println("Many");
                return;
            }

            Point p = new Point(sol[0], sol[1]);

            boolean ok = true;
            double d0 = Math.abs(lines[0].a * p.x + lines[0].b * p.y + lines[0].c);
            for (int i = 1; i < n; i++) {
                double di = Math.abs(lines[i].a * p.x + lines[i].b * p.y + lines[i].c);
                if (Math.abs(di - d0) > 1e-7) {
                    ok = false;
                    break;
                }
            }
            if (!ok) continue;

            boolean exists = false;
            for (Point q : pts) {
                if (samePoint(p, q)) {
                    exists = true;
                    break;
                }
            }
            if (!exists) pts.add(p);
            if (pts.size() > 1) {
                System.out.println("Many");
                return;
            }
        }

        if (pts.isEmpty()) {
            System.out.println("None");
        } else {
            Point p = pts.get(0);
            if (Math.abs(p.x) < 5e-13) p.x = 0;
            if (Math.abs(p.y) < 5e-13) p.y = 0;
            System.out.printf(Locale.US, "%.10f %.10f%n", p.x, p.y);
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        Integer nextIntNullable() throws IOException {
            String s = next();
            if (s == null) return null;
            return Integer.parseInt(s);
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
}

import sys
