    n = int(input_data[0])
    lines = []
    idx = 1
    for _ in range(n):
        a = float(input_data[idx]); b = float(input_data[idx+1]); c = float(input_data[idx+2])
        idx += 3
        # normalize
        norm = math.hypot(a, b)
        if norm == 0:
            continue
        lines.append((a/norm, b/norm, c/norm))

    if len(lines) == 0:
        print("No solution")
        return

    def dist_to_line(px, py, a, b, c):
        return abs(a*px + b*py + c)

    solutions = set()
    eps = 1e-9

    # single line case: any point on it is equally distant (distance=0)
    if len(lines) == 1:
        print("Single solution")
        return

    # two lines case
    if len(lines) == 2:
        a1,b1,c1 = lines[0]
        a2,b2,c2 = lines[1]
        det = a1*b2 - a2*b1
        if abs(det) > eps:
            x = (b1*c2 - b2*c1) / det
            y = (c1*a2 - c2*a1) / det
            print(f"{x:.10f} {y:.10f}")
        else:
            # parallel lines
            if abs(c1 - c2) < eps:
                print("Multiple solutions")
            else:
                # midline
                if abs(a1) > eps:
                    # vertical-ish case
                    pass
                # General midline: average of c's
                mid_c = (c1 + c2) / 2
                # a1 x + b1 y + mid_c = 0
                # pick a point
                if abs(a1) > eps:
                    x = -mid_c / a1
                    y = 0.0
                else:
                    x = 0.0
                    y = -mid_c / b1
                print(f"{x:.10f} {y:.10f}")
        return

    # general case: try all intersection points from pairs of lines
    for i in range(len(lines)):
        for j in range(i+1, len(lines)):
            a1,b1,c1 = lines[i]
            a2,b2,c2 = lines[j]
            det = a1*b2 - a2*b1
            if abs(det) < eps:
                continue
            x = (b1*c2 - b2*c1) / det
            y = (c1*a2 - c2*a1) / det
            # check distances
            d0 = dist_to_line(x, y, *lines[0])
            ok = True
            for k in range(1, len(lines)):
                if abs(dist_to_line(x, y, *lines[k]) - d0) > eps:
                    ok = False
                    break
            if ok:
                solutions.add((round(x, 10), round(y, 10)))

    if len(solutions) == 0:
        print("No solution")
    elif len(solutions) == 1:
        x,y = next(iter(solutions))
        print(f"{x:.10f} {y:.10f}")
    else:
        print("Multiple solutions")

