import sys
import math

EPS = 1e-9

def sgn(x):
    if x > EPS:
        return 1
    if x < -EPS:
        return -1
    return 0

def normalize_line(a, b, c):
    # Normalize so sqrt(a^2+b^2)=1 and canonical sign
    norm = math.hypot(a, b)
    if norm < EPS:
        return None
    a /= norm
    b /= norm
    c /= norm
    # canonical orientation
    if a < -EPS or (abs(a) <= EPS and b < -EPS):
        a, b, c = -a, -b, -c
    return (a, b, c)

def solve_linear_2x2(a1, b1, c1, a2, b2, c2):
    # a1 x + b1 y = c1
    # a2 x + b2 y = c2
    det = a1 * b2 - a2 * b1
    if abs(det) < EPS:
        return None
    x = (c1 * b2 - c2 * b1) / det
    y = (a1 * c2 - a2 * c1) / det
    return (x, y)

def line_equal(L1, L2):
    return abs(L1[0]-L2[0]) < EPS and abs(L1[1]-L2[1]) < EPS and abs(L1[2]-L2[2]) < EPS

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Assume input format:
    # n
    # a b c   (n lines)
    it = iter(data)
    try:
        n = int(next(it))
    except StopIteration:
        return

    raw = []
    for _ in range(n):
        try:
            a = float(next(it))
            b = float(next(it))
            c = float(next(it))
        except StopIteration:
            return
        nl = normalize_line(a, b, c)
        if nl is None:
            print("No solution")
            return
        raw.append(nl)

    # Remove exact duplicate normalized lines
    lines = []
    for L in raw:
        found = False
        for M in lines:
            if line_equal(L, M):
                found = True
                break
        if not found:
            lines.append(L)

    m = len(lines)

    # For one unique line: infinitely many points at distance 0
    if m <= 1:
        print("Multiple solutions")
        return

    # For a point (x,y) to be equally distant from all lines,
    # there must exist signs s_i in {+1,-1} and value t >= 0 such that:
    # a_i x + b_i y + c_i = s_i * t
    # Hence for all i>0:
    # (a_i-a_0)x + (b_i-b_0)y = s_i t - s_0 t - (c_i-c_0)
    # = (s_i-s_0)t - (c_i-c_0)
    #
    # Unknowns: x,y,t. Since s_0 can be fixed to +1 by flipping all signs,
    # enumerate sign choices for remaining lines.

    base = lines[0]
    candidates = []
    seen = []

    # Enumerate sign assignments
    # mask bit i-1 gives sign of line i: 0 => +1, 1 => -1
    total_masks = 1 << (m - 1)
    for mask in range(total_masks):
        eqs = []
        s0 = 1
        for i in range(1, m):
            si = -1 if ((mask >> (i - 1)) & 1) else 1
            a = lines[i][0] - base[0]
            b = lines[i][1] - base[1]
            d = si - s0
            rhs = -(lines[i][2] - base[2])
            eqs.append((a, b, d, rhs))

        # Solve 3-variable linear system using up to 3 independent equations.
        # Find a unique candidate if rank 3, or parametric otherwise.
        # We'll use Gaussian elimination on augmented matrix.
        mat = [list(row) for row in eqs]  # [a,b,d,rhs]
        rows = len(mat)
        pivot_cols = []
        r = 0
        for col in range(3):
            piv = None
            for i in range(r, rows):
                if abs(mat[i][col]) > EPS:
                    piv = i
                    break
            if piv is None:
                continue
            mat[r], mat[piv] = mat[piv], mat[r]
            div = mat[r][col]
            for j in range(col, 4):
                mat[r][j] /= div
            for i in range(rows):
                if i != r and abs(mat[i][col]) > EPS:
                    factor = mat[i][col]
                    for j in range(col, 4):
                        mat[i][j] -= factor * mat[r][j]
            pivot_cols.append(col)
            r += 1
            if r == rows:
                break

        # Check inconsistency
        bad = False
        for i in range(rows):
            if abs(mat[i][0]) < EPS and abs(mat[i][1]) < EPS and abs(mat[i][2]) < EPS and abs(mat[i][3]) > EPS:
                bad = True
                break
        if bad:
            continue

        if len(pivot_cols) < 2:
            # Too many degrees of freedom => likely multiple solutions for this sign pattern
            print("Multiple solutions")
            return

        if len(pivot_cols) < 3:
            # One free variable; if any solution exists, almost always infinitely many.
            print("Multiple solutions")
            return

        # Extract unique x,y,t
        sol = [0.0, 0.0, 0.0]
        for i, col in enumerate(pivot_cols):
            sol[col] = mat[i][3]
        x, y, t = sol

        if t < -EPS:
            continue

        # Verify against all lines
        ok = True
        dist0 = abs(base[0] * x + base[1] * y + base[2])
        for L in lines:
            dist = abs(L[0] * x + L[1] * y + L[2])
            if abs(dist - dist0) > 1e-7:
                ok = False
                break
        if not ok:
            continue

        # Deduplicate candidates
        dup = False
        for px, py in seen:
            if abs(px - x) < 1e-7 and abs(py - y) < 1e-7:
                dup = True
                break
        if not dup:
            seen.append((x, y))
            candidates.append((x, y))

    if len(candidates) == 0:
        print("No solution")
    elif len(candidates) > 1:
        print("Multiple solutions")
    else:
        x, y = candidates[0]
        if abs(x) < 5e-10:
            x = 0.0
        if abs(y) < 5e-10:
            y = 0.0
        print(f"{x:.10f} {y:.10f}")

if __name__ == "__main__":
    main()
